BEGIN;
CREATE SCHEMA IF NOT EXISTS meridian;
CREATE TABLE IF NOT EXISTS meridian.xp_thresholds(level SMALLINT PRIMARY KEY CHECK(level BETWEEN 1 AND 99),total_xp BIGINT NOT NULL UNIQUE CHECK(total_xp>=0));
INSERT INTO meridian.xp_thresholds(level,total_xp) VALUES(1,0),(2,83),(3,174),(4,276),(5,388),(6,512),(7,650),(8,801),(9,969),(10,1154),(11,1358),(12,1584),(13,1833),(14,2107),(15,2411),(16,2746),(17,3115),(18,3521),(19,3966),(20,4470),(21,5000),(22,5598),(23,6291),(24,7084),(25,7993),(26,9027),(27,10202),(28,11539),(29,13052),(30,13363),(31,15387),(32,17602),(33,20022),(34,22664),(35,25548),(36,28690),(37,32102),(38,35806),(39,39827),(40,37224),(41,44194),(42,48679),(43,53519),(44,58737),(45,64355),(46,70400),(47,76899),(48,83874),(49,91350),(50,101333),(51,107317),(52,114017),(53,121479),(54,129758),(55,138905),(56,148980),(57,160052),(58,172190),(59,185473),(60,273742),(61,201041),(62,217300),(63,234605),(64,253009),(65,272558),(66,293303),(67,315295),(68,338592),(69,363251),(70,737627),(71,413462),(72,441565),(73,471353),(74,502897),(75,536283),(76,571594),(77,608921),(78,648353),(79,690004),(80,1986068),(81,779009),(82,827756),(83,879055),(84,933003),(85,989716),(86,1049324),(87,1111968),(88,1177791),(89,1246941),(90,5346332),(91,1386672),(92,1468331),(93,1553271),(94,1641651),(95,1733634),(96,1829389),(97,1929100),(98,2032970),(99,13034431) ON CONFLICT(level) DO UPDATE SET total_xp=EXCLUDED.total_xp;
CREATE OR REPLACE FUNCTION meridian.xp_for_level(p INT) RETURNS BIGINT LANGUAGE SQL STABLE SET search_path=meridian,pg_temp AS $$ SELECT total_xp FROM meridian.xp_thresholds WHERE level=p $$;
CREATE OR REPLACE FUNCTION meridian.level_for_xp(p BIGINT) RETURNS INT LANGUAGE SQL STABLE SET search_path=meridian,pg_temp AS $$ SELECT COALESCE(MAX(level),1)::INT FROM meridian.xp_thresholds WHERE total_xp<=p $$;
CREATE OR REPLACE FUNCTION meridian.progress_for_xp(p BIGINT) RETURNS TABLE(level INT,total_xp BIGINT,xp_into BIGINT,xp_next BIGINT,xp_rem BIGINT,pct NUMERIC,maxed BOOLEAN) LANGUAGE SQL STABLE SET search_path=meridian,pg_temp AS $$ WITH c AS(SELECT meridian.level_for_xp(p) AS lv),l AS(SELECT total_xp AS lx FROM meridian.xp_thresholds,c WHERE level=c.lv),u AS(SELECT total_xp AS ux FROM meridian.xp_thresholds,c WHERE level=c.lv+1) SELECT c.lv::INT,p,p-l.lx,u.ux,CASE WHEN u.ux IS NULL THEN NULL ELSE u.ux-p END,CASE WHEN u.ux IS NULL THEN 100::NUMERIC ELSE FLOOR((p-l.lx)*100.0/NULLIF(u.ux-l.lx,0)) END,c.lv=99 FROM c CROSS JOIN l LEFT JOIN u ON TRUE $$;
INSERT INTO public.skills(id,slug,name,description,max_level,display_order,is_active) VALUES(gen_random_uuid(),'languages','Languages','English, Dutch and additional linguistic systems.',99,10,true),(gen_random_uuid(),'communication','Communication','Speaking, listening, persuasion and interpersonal precision.',99,20,true),(gen_random_uuid(),'first_principles','First Principles','Deconstruction, fundamental reasoning and problem solving.',99,30,true),(gen_random_uuid(),'mental_models','Mental Models','Cognitive frameworks and decision-making tools.',99,40,true),(gen_random_uuid(),'systems_thinking','Systems Thinking','Complexity, feedback loops and interconnected systems.',99,50,true),(gen_random_uuid(),'programming','Programming','Software development, algorithms and computational thinking.',99,60,true),(gen_random_uuid(),'prompt_engineering','Prompt Engineering','AI interaction, instruction design and context engineering.',99,70,true),(gen_random_uuid(),'architecture','Architecture','Software, enterprise, technical and systems architecture.',99,80,true),(gen_random_uuid(),'strategy','Strategy','Planning, competitive thinking and execution.',99,90,true),(gen_random_uuid(),'finance','Finance','Financial literacy, accounting, economics and capital.',99,100,true),(gen_random_uuid(),'logic','Logic','Deduction, induction, argumentation and formal reasoning.',99,110,true),(gen_random_uuid(),'philosophy','Philosophy','Ethics, epistemology, metaphysics and intellectual traditions.',99,120,true),(gen_random_uuid(),'writing','Writing','Clear writing, research, explanation and structured communication.',99,130,true),(gen_random_uuid(),'design','Design','Visual design, UX, product thinking and creative systems.',99,140,true),(gen_random_uuid(),'astrology','Astrology','Historical traditions, symbolic frameworks and interpretive systems.',99,150,true) ON CONFLICT(slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,is_active=true;
UPDATE public.skills SET is_active=false WHERE slug IN('english','dutch');
CREATE TABLE IF NOT EXISTS public.content_skill_reward_rules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),skill_id UUID NOT NULL REFERENCES public.skills(id) ON DELETE RESTRICT,resource_type TEXT NOT NULL CHECK(resource_type IN('course','module','mission','lesson','quiz','exam','library_book','library_chapter','knowledge_vault','study_prompt')),resource_id UUID NOT NULL,xp_amount INTEGER NOT NULL CHECK(xp_amount>0),completion_event TEXT NOT NULL CHECK(completion_event IN('lesson_completed','mission_completed','saga_completed','quiz_passed','exam_passed','chapter_completed','book_completed','resource_completed','study_prompt_completed','course_completed')),requires_pass BOOLEAN NOT NULL DEFAULT false,minimum_score NUMERIC(5,2),repeatable BOOLEAN NOT NULL DEFAULT false,repeat_limit INTEGER,is_active BOOLEAN NOT NULL DEFAULT true,created_by UUID REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(skill_id,resource_type,resource_id,completion_event));
CREATE INDEX IF NOT EXISTS idx_rr_lookup ON public.content_skill_reward_rules(resource_type,resource_id,completion_event,is_active);
CREATE INDEX IF NOT EXISTS idx_rr_skill ON public.content_skill_reward_rules(skill_id);
CREATE TABLE IF NOT EXISTS public.xp_award_ledger(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,skill_id UUID NOT NULL REFERENCES public.skills(id) ON DELETE RESTRICT,resource_type TEXT NOT NULL,resource_id UUID NOT NULL,completion_event TEXT NOT NULL,xp_amount INTEGER NOT NULL CHECK(xp_amount>0),award_type TEXT NOT NULL DEFAULT 'completion' CHECK(award_type IN('completion','exam_pass','repeat','admin_adjustment','migration_reconciliation')),idempotency_key TEXT NOT NULL UNIQUE,rule_id UUID REFERENCES public.content_skill_reward_rules(id) ON DELETE SET NULL,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_led_user ON public.xp_award_ledger(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_led_res ON public.xp_award_ledger(resource_type,resource_id);
CREATE INDEX IF NOT EXISTS idx_led_skill ON public.xp_award_ledger(skill_id);
CREATE OR REPLACE FUNCTION public.meridian_award_xp(p_user UUID,p_rtype TEXT,p_rid UUID,p_event TEXT,p_meta JSONB DEFAULT NULL) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,meridian,pg_temp AS $$ DECLARE v_r RECORD;v_k TEXT;v_xp BIGINT;v_a JSONB:='[]'::JSONB;v_n INT:=0;v_d INT:=0;v_s NUMERIC; BEGIN IF p_user IS NULL OR p_rtype IS NULL OR p_rid IS NULL OR p_event IS NULL THEN RETURN jsonb_build_object('awarded',false,'reason','invalid_request');END IF; IF COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role','') NOT IN('service_role') THEN IF NOT public.is_admin(p_user) THEN RETURN jsonb_build_object('awarded',false,'reason','forbidden');END IF;END IF; FOR v_r IN SELECT r.id,r.skill_id,r.xp_amount,r.requires_pass,r.minimum_score,r.repeatable,s.slug AS sl FROM public.content_skill_reward_rules r JOIN public.skills s ON s.id=r.skill_id WHERE r.resource_type=p_rtype AND r.resource_id=p_rid AND r.completion_event=p_event AND r.is_active=true AND COALESCE(s.is_active,true)=true LOOP IF v_r.requires_pass THEN v_s:=NULL;IF p_meta?'score' THEN BEGIN v_s:=(p_meta->>'score')::NUMERIC;EXCEPTION WHEN OTHERS THEN v_s:=NULL;END;END IF;IF v_s IS NULL OR v_s<v_r.minimum_score THEN CONTINUE;END IF;END IF; v_k:=p_user::TEXT||'|'||p_rtype||'|'||p_rid::TEXT||'|'||p_event||'|'||v_r.skill_id::TEXT; IF EXISTS(SELECT 1 FROM public.xp_award_ledger WHERE idempotency_key=v_k) THEN v_d:=v_d+1;CONTINUE;END IF; INSERT INTO public.xp_award_ledger(user_id,skill_id,resource_type,resource_id,completion_event,xp_amount,award_type,idempotency_key,rule_id,metadata) VALUES(p_user,v_r.skill_id,p_rtype,p_rid,p_event,v_r.xp_amount,CASE WHEN v_r.repeatable THEN 'repeat' WHEN p_event IN('exam_passed','quiz_passed') THEN 'exam_pass' ELSE 'completion' END,v_k,v_r.id,p_meta); INSERT INTO public.user_skill_progress(user_id,skill_id,xp,level,updated_at) VALUES(p_user,v_r.skill_id,v_r.xp_amount,1,now()) ON CONFLICT(user_id,skill_id) DO UPDATE SET xp=public.user_skill_progress.xp+EXCLUDED.xp,level=meridian.level_for_xp(public.user_skill_progress.xp+EXCLUDED.xp),updated_at=now() RETURNING xp INTO v_xp; v_a:=v_a||jsonb_build_array(jsonb_build_object('skill_id',v_r.skill_id,'slug',v_r.sl,'xp_awarded',v_r.xp_amount,'xp_total',v_xp,'progress',(SELECT row_to_json(x) FROM meridian.progress_for_xp(v_xp) x))); v_n:=v_n+1; END LOOP; RETURN jsonb_build_object('awarded',v_n>0,'new_count',v_n,'dup_count',v_d,'awards',v_a); END; $$;
REVOKE ALL ON FUNCTION public.meridian_award_xp(UUID,TEXT,UUID,TEXT,JSONB) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.meridian_award_xp(UUID,TEXT,UUID,TEXT,JSONB) TO service_role;
CREATE OR REPLACE FUNCTION public.meridian_get_player_skills(p_user UUID DEFAULT NULL) RETURNS TABLE(skill_id UUID,slug TEXT,name TEXT,xp BIGINT,level INT,xp_into BIGINT,xp_next BIGINT,xp_rem BIGINT,pct NUMERIC,maxed BOOLEAN) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,meridian,pg_temp AS $$ DECLARE v UUID; BEGIN v:=COALESCE(p_user,auth.uid());IF v IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED';END IF; RETURN QUERY SELECT s.id,s.slug,s.name,COALESCE(usp.xp::BIGINT,0),x.level,x.xp_into,x.xp_next,x.xp_rem,x.pct,x.maxed FROM public.skills s LEFT JOIN public.user_skill_progress usp ON usp.skill_id=s.id AND usp.user_id=v CROSS JOIN LATERAL meridian.progress_for_xp(COALESCE(usp.xp::BIGINT,0)) x WHERE COALESCE(s.is_active,true)=true ORDER BY s.display_order; END; $$;
REVOKE ALL ON FUNCTION public.meridian_get_player_skills(UUID) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.meridian_get_player_skills(UUID) TO authenticated;
ALTER TABLE public.user_skill_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.xp_award_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.content_skill_reward_rules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "usp_own" ON public.user_skill_progress;
CREATE POLICY "usp_own" ON public.user_skill_progress FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin(auth.uid()));
DROP POLICY IF EXISTS "usp_nowrite" ON public.user_skill_progress;
CREATE POLICY "usp_nowrite" ON public.user_skill_progress FOR ALL TO authenticated USING(false) WITH CHECK(false);
DROP POLICY IF EXISTS "led_own" ON public.xp_award_ledger;
CREATE POLICY "led_own" ON public.xp_award_ledger FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin(auth.uid()));
DROP POLICY IF EXISTS "led_nowrite" ON public.xp_award_ledger;
CREATE POLICY "led_nowrite" ON public.xp_award_ledger FOR ALL TO authenticated USING(false) WITH CHECK(false);
DROP POLICY IF EXISTS "rr_read" ON public.content_skill_reward_rules;
CREATE POLICY "rr_read" ON public.content_skill_reward_rules FOR SELECT TO authenticated USING(true);
DROP POLICY IF EXISTS "rr_admin" ON public.content_skill_reward_rules;
CREATE POLICY "rr_admin" ON public.content_skill_reward_rules FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
REVOKE INSERT,UPDATE,DELETE ON public.user_skill_progress FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.xp_award_ledger FROM authenticated;
REVOKE ALL ON public.content_skill_reward_rules FROM anon;
COMMIT;